Translate("frFR", "weldon-barov", {
	title = "Weldon Barov",
	subtitle = "Héritier de la maison Barov",
	found = "Le Camp du Noroît",
	hint = [=[Cherchez le noble orgueilleux qui s'abrite au Camp du Noroît.]=],
	allegiance = "Maison Barov · Alliance",
	aliases = { "Weldon" },
	sections = {
