		},
	},
	chapters = {
		{
			title = "Le dernier Barov",
			hint = [=[Écoutez ce que le noble du Noroît veut que l'on fasse de son frère.]=],
			text = [=[Avec les titres de {link:caer-darrow}Caer Darrow{/link}, de {link:brill}Brill{/link}, de {link:tarren-mill}Moulin-de-Tarren{/link} et de {link:southshore}Southshore{/link} entre ses mains, Weldon voulait encore une chose. Il voulait la tête de son frère, rapportée de la {link:the-bulwark}Barricade{/link}. Il ne ferait pas la besogne lui-même. De telles choses, disait-il, étaient indignes d'un homme de sa naissance.]=],
		},
	},
	mentions = {
		{ text = "La fortune de la famille Barov" },
		{ text = "Le dernier Barov" },
	},
	bonds = {
		{ id = "alexi-barov", name = "Alexi Barov", note = "son frère et rival" },
	},
})

