Translate("frFR", "nathaniel-dumah", {
	title = "Nathaniel Dumah",
	subtitle = "Fils de la Crête du nord",
	found = "Le Camp du Noroît",
	hint = "Parlez à l'homme du Camp du Noroît qui hait la Croisade.",
	allegiance = "Alliance",
	aliases = { "Dumah" },
