	chapters = {
		{
			title = "Que la peste soit sur vous",
			hint = [=[Aidez Nathaniel à ruiner la scierie dont la Croisade s'est emparée.]=],
			text = [=[Les termites de {link:plaguewood}Pestebois{/link} avaient survécu à la peste comme au {link:scourge}Fléau{/link}. Un tonneau en fut porté dans la scierie de la Crête du nord et ouvert. Nathaniel rit en apprenant que c'était fait. L'esprit de son père, dit-il, pouvait désormais reposer, et lui aussi.]=],
		},
	},
	mentions = {
