Translate("frFR", "janice-felstone", {
	title = "Janice Felstone",
	subtitle = "Le fantôme du Champ de Felstone",
	found = "La chambre du haut de la ferme du Champ de Felstone",
	hint = "Montez à la chambre du haut de la ferme des Felstone.",
	allegiance = "Aucune",
	aliases = { "Janice" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le fantôme de Janice Felstone hante sa ferme du {link:felstone-field}Champ de Felstone{/link}. Elle n'a qu'à moitié conscience du monde. Elle parle d'un colis qu'elle voulait envoyer avant la peste, et qu'elle a laissé près de son cheval dans la grange. Elle appelle son mari John et craint les goules du dehors.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle prépara un colis pour sa sœur Emma à {link:stormwind-city}Stormwind{/link}, ou pour son frère Jeremiah dans la capitale du {link:lordaeron}Lordaeron{/link}.
• Elle partagea un porte-bonheur avec son mari John, une moitié chacun.]=],
		},
	},
	chapters = {
		{
			title = "Deux moitiés ne font qu'un",
			hint = "Rendez le porte-bonheur entier.",
			text = [=[Le colis parvint à son destinataire avec des années de retard. Emma, la sœur de Janice, errait désormais dans les rues de {link:stormwind-city}Stormwind{/link}. Son frère Jeremiah était devenu l'un des {link:forsaken}Réprouvés{/link}, et il avait changé de nom. Qui que ce soit qui le reçut renvoya la moitié du porte-bonheur de Janice. L'autre moitié était toujours à la ferme. Quand le porte-bonheur fut reconstitué et placé entre ses mains, le regard du fantôme s'éclaircit. Elle était libre.]=],
		},
	},
	mentions = {
		{ text = "Mieux vaut tard que jamais" },
		{ text = "Porte-bonheur" },
		{ text = "Deux moitiés ne font qu'un" },
	},
})

Translate("frFR", "farmer-dalson", {
	title = "Fermier Dalson",
	subtitle = "La chose dans les latrines",
	found = "Enfermé dans les latrines des Larmes de Dalson",
