	chapters = {
		{
			title = "Sous clé",
			hint = "Ouvrez ce que Mme Dalson a enfermé.",
			text = [=[Mme Dalson ne quitta jamais la ferme. Son squelette erre toujours dans la cour, et la clé des latrines était toujours sur lui. Quand la porte fut ouverte, une goule en jaillit en hurlant. Harold ne pouvait plus être sauvé.]=],
		},
	},
	mentions = {
		{ text = "Le journal de Mme Dalson" },
		{ text = "Sous clé" },
	},
})

Translate("frFR", "marlene-redpath", {
