Translate("frFR", "mulgris-deepriver", {
	title = "Mulgris Deepriver",
	subtitle = "Guérisseur des bêtes",
	found = "Une chaumière du Repaire putride",
	hint = [=[Cherchez le druide mourant dans une chaumière du Repaire putride.]=],
	allegiance = "Druides du Cercle cénarien",
	aliases = { "Mulgris" },
	sections = {
		{
			title = "Résumé",
			text = [=[Mulgris Deepriver est un druide {link:tauren}tauren{/link} venu dans les {link:eastern-plaguelands}Maleterres{/link} pour guérir ce que la peste avait fait à ses bêtes. Il ne pouvait pas grand-chose seul contre le {link:scourge}Fléau{/link}, et il ne trouva aucun remède. La peste lui prit la vue, et elle lui prend le reste. Il demande seulement que les animaux malades du pays reçoivent une fin miséricordieuse.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il tenta de guérir les bêtes des {link:eastern-plaguelands}Maleterres{/link}, jusqu'à tomber malade lui-même.
• Il écrivit ce qu'il avait appris de la peste sur une branche de chêne gravée de glyphes.]=],
		},
	},
	chapters = {
		{
			title = "La faune souffre aussi",
			hint = "Accordez aux bêtes malades de la peste leur délivrance.",
			text = [=[Quand les loups et les grizzlis malades furent abattus, Mulgris sentit leurs esprits en paix. Puis il remit la branche sur laquelle il avait écrit son savoir. Il dit que les créatures de cette terre pouvaient reposer désormais, et lui aussi. Dans un dernier souffle, il mourut sur le sol de la chaumière. La branche fut portée aux druides du {link:cenarion-circle}Cercle cénarien{/link}, à {link:darnassus}Darnassus{/link} ou à {link:thunder-bluff}Thunder Bluff{/link}.]=],
		},
	},
	mentions = {
		{ text = "La faune souffre aussi" },
		{ text = "Branche de chêne gravée de glyphes" },
